import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
import '../../services/devhub_api.dart';
import '../../core/app_theme.dart';
import '../../widgets/devhub_widgets.dart';
class RequestsScreen extends StatefulWidget{const RequestsScreen({super.key});@override State<RequestsScreen> createState()=>_RequestsScreenState();}
class _RequestsScreenState extends State<RequestsScreen>{late Future<Map<String,dynamic>> future;@override void initState(){super.initState();future=context.read<DevHubApi>().requests();}
 void reload()=>setState(()=>future=context.read<DevHubApi>().requests());
 @override Widget build(BuildContext context)=>FutureBuilder<Map<String,dynamic>>(future:future,builder:(context,snap){if(snap.connectionState==ConnectionState.waiting)return const LoadingView();if(snap.hasError)return ErrorView(message:'${snap.error}',retry:reload);final data=snap.data??{};final incoming=List<dynamic>.from(data['incoming']??[]),outgoing=List<dynamic>.from(data['outgoing']??[]);return DefaultTabController(length:2,child:Column(children:[Padding(padding:const EdgeInsets.fromLTRB(18,18,18,8),child:SectionTitle('Collaboration requests',subtitle:'Invitations to build together',trailing:IconButton(onPressed:reload,icon:const Icon(Icons.refresh)))),const TabBar(tabs:[Tab(text:'Received'),Tab(text:'Sent')]),Expanded(child:TabBarView(children:[_list(incoming,true),_list(outgoing,false)]))]));});
 Widget _list(List<dynamic> items,bool incoming)=>items.isEmpty?const Center(child:Text('No collaboration requests yet.',style:TextStyle(color:AppColors.muted))):ListView(padding:const EdgeInsets.all(16),children:items.map((e){final m=Map<String,dynamic>.from(e);final person=Map<String,dynamic>.from(m[incoming?'sender':'receiver']??{});final id='${m['_id']??''}';return Padding(padding:const EdgeInsets.only(bottom:10),child:Panel(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[InitialAvatar(name:'${person['name']??person['username']??'D'}',url:'${person['avatarUrl']??''}'),const SizedBox(width:12),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('${person['name']??person['username']??'Developer'}',style:const TextStyle(fontWeight:FontWeight.bold)),Text('@${person['username']??''}',style:const TextStyle(color:AppColors.muted))])),SkillPill('${m['status']??'pending'}')]),const SizedBox(height:10),Text('${m['message']??''}',style:const TextStyle(color:AppColors.muted)),if(incoming&&m['status']=='pending')Row(mainAxisAlignment:MainAxisAlignment.end,children:[TextButton(onPressed:()=>_update(id,'rejected'),child:const Text('Decline')),const SizedBox(width:8),ElevatedButton(onPressed:()=>_update(id,'accepted'),child:const Text('Accept'))])])));}).toList());
 Future<void> _update(String id,String status)async{try{await context.read<DevHubApi>().updateRequest(id,status);reload();}catch(e){if(context.mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.toString())));}}
}
